/// This type characterizes the agility pattern driving a Signal with agile frequency modulation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum FrequencyAgilityPatternEnum {
    /// Indicates an agile Signal driven by a sawtooth pattern.
    #[serde(rename = "SAWTOOTH")]
    Sawtooth,
    /// Indicates an agile Signal driven by a triangle pattern.
    #[serde(rename = "TRIANGLE")]
    Triangle,
    /// Indicates an agile Signal driven by a sine pattern.
    #[serde(rename = "SINUSOID")]
    Sinusoid,
    /// Indicates an agile Signal driven by a seemingly random pattern.
    #[serde(rename = "RANDOM")]
    Random,
    /// Indicates an agile Signal driven by a non-repeating, piecewise monotonically changing modulation
    /// pattern.
    #[serde(rename = "SLIDE")]
    Slide,
    /// Indicates an agile Signal whose agility pattern is unknown despite an attempt to characterize
    /// it.
    #[serde(rename = "UNKNOWN")]
    Unknown,
}

/// This type characterizes the variation in frequency of a Signal, pulse-to-pulse for a pulsed
/// signal or over time for a CW signal. The enumerated literals are not mutually exclusive to allow
/// for the use of NDI systems with varying measurement capabilities.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum FrequencyModulationVariationEnum {
    /// Indicates a fixed frequency Signal with no detectable intentional modulation.
    #[serde(rename = "STABLE")]
    Stable,
    /// Indicates a Signal with frequency modulation that has been identified as non-stable but can't be
    /// characterized as jitter, switched, stagger, etc.
    #[serde(rename = "NON_STABLE")]
    NonStable,
    /// Indicates a fixed frequency Signal with detectable but seemingly random frequency variation.
    #[serde(rename = "JITTER")]
    Jitter,
    /// Indicates a Signal with frequency modulation that changes over time through switches between a
    /// limited set of discrete modulations. Characteristics of the switching are given by other data
    /// elements.
    #[serde(rename = "SWITCHED")]
    Switched,
    /// Indicates a Signal with frequency modulation that changes over time by progressing through a
    /// fixed sequence of discrete modulations, referred to as a "pattern", that repeats. Individual
    /// frequencies in the pattern are referred to as "levels". Characteristics of the pattern and
    /// levels are given by other data elements.
    #[serde(rename = "STAGGER")]
    Stagger,
    /// Indicates a Signal with frequency modulation that changes over time through a continuous
    /// pattern. Characteristics of the agility pattern are given by other data elements.
    #[serde(rename = "AGILE")]
    Agile,
    /// Indicates a Signal whose frequency modulation is unknown despite an attempt to characterize it.
    #[serde(rename = "UNKNOWN")]
    Unknown,
}

/// Indicates a frequency offset in Hertz (Hz).
pub type FrequencyOffsetType = f64;

/// This type characterizes the periodicity of a Signal's frequency modulation pattern.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum FrequencyPatternPeriodicityEnum {
    /// Indicates a Signal whose frequency pattern repeats periodically.
    #[serde(rename = "PERIODIC")]
    Periodic,
    /// Indicates a Signal whose frequency pattern does not repeat periodically.
    #[serde(rename = "APERIODIC")]
    Aperiodic,
}

/// This type characterizes the nature of the frequency values that make up the switched frequency
/// Signal.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum FrequencySwitchingEnum {
    /// Indicates the switched frequencies of a Signal are selected from a continuous set.
    #[serde(rename = "CONTINUOUS")]
    Continuous,
    /// Indicates the switched frequencies of a Signal are selected from a discrete, non-continuous set.
    #[serde(rename = "DISCRETE")]
    Discrete,
}

/// This type characterizes the switching pattern of a Signal with switched frequency modulation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum FrequencySwitchingPatternEnum {
    /// Indicates a switched Signal using a limited set of discrete frequency values where switches are
    /// often synchronized with changes in other Signal parameters such as PRI and PW.
    #[serde(rename = "DWELL_SCAN")]
    DwellScan,
    /// Indicates a switched Signal alternating between two discrete frequency values.
    #[serde(rename = "ALTERNATING")]
    Alternating,
    /// Indicates a switched Signal using a limited set of discrete frequency where switches occur in a
    /// seemingly random order.
    #[serde(rename = "RANDOM")]
    Random,
}

/// Indicates a (positive) frequency in Hertz (Hz).
pub type FrequencyType = DoublePositiveType;

