/// Indicates the polarization of electromagnetic waves.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum PolarizationEnum {
    /// Indicates no polarization detected.
    #[serde(rename = "NONE")]
    None,
    /// The polarization rotates at a constant rate perpendicular to the propagation.
    #[serde(rename = "CIRCULAR")]
    Circular,
    /// The linear polarization is horizontal to the reference plane.
    #[serde(rename = "HORIZONTAL")]
    Horizontal,
    /// No annotation will be provided.
    #[serde(rename = "ROTATING")]
    Rotating,
    /// The linear polarization is vertical to the reference plane.
    #[serde(rename = "VERTICAL")]
    Vertical,
    /// The polarization is +/- 45 degrees from the reference plane.
    #[serde(rename = "SLANT")]
    Slant,
    /// Polarization in which the electric field vector is confined to a given plane along the direction
    /// of propagation.
    #[serde(rename = "LINEAR")]
    Linear,
    /// Left circular polarization in which the electric field vector rotates in a left-hand sense with
    /// respect to the direction of propagation.
    #[serde(rename = "LEFT_CIRCULAR")]
    LeftCircular,
    /// Right circular polarization in which the electric field vector rotates in a right-hand sense
    /// with respect to the direction of propagation.
    #[serde(rename = "RIGHT_CIRCULAR")]
    RightCircular,
    /// The polarization is orthogonal to the polarization of the reference wave.
    #[serde(rename = "ORTHOGONAL")]
    Orthogonal,
    /// The polarization is in the same principal direction as the reference wave.
    #[serde(rename = "PRINCIPAL")]
    Principal,
    /// The electromagnetic waves do not have any polarization.
    #[serde(rename = "UNPOLARIZED")]
    Unpolarized,
}

/// Indicates left or right handed polarization.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum PolarizationSenseEnum {
    /// Right circular polarization in which the electric field vector rotates in a right-hand sense
    /// with respect to the direction of propagation.
    #[serde(rename = "RIGHT_HANDED")]
    RightHanded,
    /// Left circular polarization in which the electric field vector rotates in a left-hand sense with
    /// respect to the direction of propagation.
    #[serde(rename = "LEFT_HANDED")]
    LeftHanded,
}

