/// Indicates which MIL-STD-6016 enumeration should be used to interpret the WeatherKind.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum WeatherKindEnum {
    /// Indicates that no significant weather exists.
    #[serde(rename = "NO_SIGNIFICANT_WEATHER")]
    NoSignificantWeather,
    /// Indicates that drizzle (light rain) exists.
    #[serde(rename = "DRIZZLE")]
    Drizzle,
    /// Indicates that it is raining.
    #[serde(rename = "RAIN")]
    Rain,
    /// Indicates that it is currently snowing.
    #[serde(rename = "SNOW")]
    Snow,
    /// Snow grains are characterized by small (less than 1mm) grains of ice.
    #[serde(rename = "SNOW_GRAINS")]
    SnowGrains,
    /// Diamond dust is characterized by a ground-level cloud composed of tiny ice crystals.
    #[serde(rename = "DIAMOND_DUST")]
    DiamondDust,
    /// Ice pellets are a form of precipitation consisting of small, translucent balls of ice, also
    /// known as sleet.
    #[serde(rename = "ICE_PELLETS")]
    IcePellets,
    /// Hail is characterized as solid precipitation.
    #[serde(rename = "HAIL")]
    Hail,
    /// Hail snow pellets are characterized as supercooled water droplets, also known as "soft hail" or
    /// "graupel".
    #[serde(rename = "SMALL_HAIL_SNOW_PELLETS")]
    SmallHailSnowPellets,
    /// Mist is characterized as tiny water droplets suspended in the atmosphere near the earths
    /// surface.
    #[serde(rename = "MIST")]
    Mist,
    /// Fog is characterized as visible aerosol consisting of tiny water droplets or ice crystals
    /// suspended in the air near the earths surface.
    #[serde(rename = "FOG")]
    Fog,
    /// Smoke is characterized as visible suspension of carbon or other particles in the air.
    #[serde(rename = "SMOKE")]
    Smoke,
    /// Volcanic is characterized as fragments of rock, minerals, and volcanic glass, created during
    /// volcanic eruptions.
    #[serde(rename = "VOLCANIC_ASH")]
    VolcanicAsh,
    /// Widespread dust is characterized as loose dirt/sand suspended in the atmosphere.
    #[serde(rename = "WIDESPREAD_DUST")]
    WidespreadDust,
    /// Sand is characterized as visible suspension of sand in the atmosphere.
    #[serde(rename = "SAND")]
    Sand,
    /// Haze is characterized as dust, smoke, or other dry particles obscure the clarity of the sky.
    #[serde(rename = "HAZE")]
    Haze,
    /// Sand/dust swirls are characterized as an ensemble of particles of dust or sand, sometimes
    /// accompanied by small litter, raised from the ground in the form of a whirling column of varying
    /// height with a small diameter and approximately vertical axis.
    #[serde(rename = "DUST_SAND_WHIRLS")]
    DustSandWhirls,
    /// Squalls are characterized as a sudden, sharp increase in wind speed lasting minutes, contrary to
    /// a wind gust lasting seconds.
    #[serde(rename = "SQUALLS")]
    Squalls,
    /// Funnel-shaped cloud of condensed water droplets, associated with a rotating column of wind and
    /// extending from the base of a cloud but not reaching the surface.
    #[serde(rename = "FUNNEL_CLOUDS")]
    FunnelClouds,
    /// Sandstorms are characterized by strong wind blowing clouds of loose sand and dirt.
    #[serde(rename = "SANDSTORM")]
    Sandstorm,
    /// Duststorms are characterized by strong wind blowing fine particles long distances.
    #[serde(rename = "DUSTSTORM")]
    Duststorm,
}

