/// Information on offsets between time systems and on polar motion, both of which are available
/// from the Naval Observatory International Earth Rotation Service.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TimeAndPolarDataType {
    /// TAI - UTC. Difference between International Atomic Time (TAI) and Coordinated Universal Time
    /// (UTC), number of leap seconds since the beginning of GPS time, always a whole number of seconds.
    #[serde(rename = "TAI_UTC_Difference")]
    pub tai_utc_difference: i32,
    /// UT1 - UTC offset, units of seconds. A common range is (-10,10).
    #[serde(rename = "UT1_UTC_Difference")]
    pub ut1_utc_difference: f64,
    /// Indicates the linear drift of UT1-UTC, units of msec/day. A common range is (-10,10).
    #[serde(rename = "UT1_Rate")]
    pub ut1_rate: f64,
    /// Indicates the x and y coordinates of polar motion. Reference
    /// http://www.iers.org/IERS/EN/Science/EarthRotation/PolarMotion.html.
    #[serde(rename = "PolarMotion")]
    pub polar_motion: PolarMotionType,
    /// Represents the number of terms of the nutation model to be used.
    #[serde(rename = "NutationModelTerms")]
    pub nutation_model_terms: i32,
    /// Time of the next scheduled leap second. May be omitted if the information is unknown or
    /// unscheduled.
    #[serde(rename = "NextLeapSecond")]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub next_leap_second: Option<DateTimeType>,
}

